import { HttpErrorResponse } from '@angular/common/http';
import { error } from '@angular/compiler/src/util';
import { Component, OnInit } from '@angular/core';
import { FormControl, FormGroup, NgForm } from '@angular/forms';
import { Router } from '@angular/router';
import { Alert } from 'selenium-webdriver';
import { laboratory } from '../../model/laboratory';
import { LaboratoryService } from '../../services/laboratory.service';

@Component({
  selector: 'app-laboratory',
  templateUrl: './laboratory.component.html',
  styleUrls: ['./laboratory.component.scss']
})
export class LaboratoryComponent implements OnInit {

  constructor(private laboratoryservice: LaboratoryService ,private router :Router) { }

  ngOnInit(): void {
    this.get_all();
  }

  laboratorys: laboratory[];
  content_laboratory: boolean;
  public get_all() {
    this.laboratoryservice.get_all_laboratory().subscribe(
      data => {
        if (data.status == 200) {
          this.laboratorys = data.body;
          this.content_laboratory = true;
        }
        else if (data.status == 204) {
          this.content_laboratory = false;
        }
      }, 
      (error: HttpErrorResponse) => {
        if (error.status ==403) {
          localStorage.clear();
          this.laboratoryservice.clear();
          this.router.navigateByUrl('/login');
        }
      }
    )
  }



  laboratory_update: laboratory;
  new_value = "";
  public update(laboratory: laboratory) {
    if (window.confirm('Are you sure')) {
      this.new_value = (<HTMLInputElement>document.getElementById("laboratory_update_country")).value;
      laboratory.country = this.new_value;
      this.laboratoryservice.update_laboratory(laboratory).subscribe(
        (response: string) => {
          this.get_all();
          this.alert('Laboratory successfully updated', 'warning');

        },
      
        (error: HttpErrorResponse) => {
          if (error) {
            console.log(error.message); console.log(error.status)
          }
        }
        )
    }
  }
  public set(laboratory: laboratory) {
    this.laboratory_update = laboratory;
    (<HTMLInputElement>document.getElementById("laboratory_update_country")).value = laboratory.country;

  }


  public delete(laboratoryname: string) {
    if (window.confirm('Are you sure')) {
      this.laboratoryservice.delete_laboratory(laboratoryname).subscribe(
        (response: string) => {
          this.get_all()
          this.alert('Laboratory successfully deleted', 'danger');

        }
      ,
        (error: HttpErrorResponse) => {
          if (error) { console.log(error.message); console.log(error.status) }
        })
    }
  }

  new_laboratory: laboratory;
  existe: boolean;
  n:boolean;
  add_laboratory(laboratory: NgForm) {
    this.new_laboratory = laboratory.value;
    this.new_laboratory.loginuser = localStorage.getItem("current_user_id");
    this.laboratoryservice.add_laboratory(this.new_laboratory).subscribe(
      (response) => {
        if (response== "201") {
          this.existe=false;
          this.get_all();
          this.alert('Laboratory successfully added', 'primary');
          laboratory.resetForm();
          this.hide()
        }
        else if 
        (response == "200")
        { this.existe=true;}
      },
      (error: HttpErrorResponse) => {
        if (error) { if (error.status == 403) {
          localStorage.clear();
          this.laboratoryservice.clear();
          this.router.navigateByUrl('/login');
        }}
      }
      )
  }

  hide() {
    let element: HTMLElement = document.getElementById('r') as HTMLElement;
    element.click();
  }

  cancel_add(laboratory: NgForm)
  {
    laboratory.resetForm();
    this.existe=false;
  }

  alertsDismiss: any = [];
  alert(msg: string, type: string) {
    this.alertsDismiss.push({
      type: type,
      msg: msg,
      timeout: 2500
    });
  }

}
